/* @component: custom-select */
(function () {
  if (window.__customSelectInit) return;
  window.__customSelectInit = true;

  function openSelect(select, list) {
    select.classList.add('_is-active');
    list.style.display = 'block';
    list.style.pointerEvents = 'auto';
    list.style.overflow = 'hidden';

    list.style.paddingTop = '';
    list.style.paddingBottom = '';
    list.style.borderTopWidth = '';
    list.style.borderBottomWidth = '';

    list.style.transition = 'none';
    list.style.height = 'auto';
    var target = list.scrollHeight;
    list.style.height = '0px';
    list.style.opacity = '0';

    list.offsetHeight;

    list.style.transition = 'height 0.28s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.22s ease, padding 0.28s ease, border-width 0.28s ease';
    list.style.opacity = '1';
    list.style.height = target + 'px';
  }

  function closeSelect(select, list) {
    list.style.overflow = 'hidden';
    list.style.pointerEvents = 'none';

    var start = list.scrollHeight || list.offsetHeight;
    list.style.transition = 'none';
    list.style.height = start + 'px';
    list.style.opacity = '1';

    list.offsetHeight;

    list.style.transition = 'height 0.28s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.22s ease, padding 0.28s ease, border-width 0.28s ease';
    list.style.opacity = '0';
    list.style.height = '0px';
    list.style.paddingTop = '0px';
    list.style.paddingBottom = '0px';
    list.style.borderTopWidth = '0px';
    list.style.borderBottomWidth = '0px';

    select.classList.remove('_is-active');
  }

  document.addEventListener('transitionend', function (e) {
    if (e.propertyName === 'height' && e.target.classList.contains('dropdown-list')) {
      var list = e.target;
      var select = list.closest('.custom-select');
      if (select && select.classList.contains('_is-active')) {
        list.style.height = 'auto';
        list.style.overflow = 'visible';
      } else {
        list.style.display = 'none';
        list.style.paddingTop = '';
        list.style.paddingBottom = '';
        list.style.borderTopWidth = '';
        list.style.borderBottomWidth = '';
      }
    }
  });

  document.addEventListener('click', function (e) {
    var clickedItem = e.target.closest('.dropdown-list__item');
    if (clickedItem) {
      var select = clickedItem.closest('.custom-select');
      if (!select) return;
      var list = select.querySelector('.dropdown-list');
      var span = select.querySelector('.dropdown-button span');
      var hidden = select.querySelector('input[type="hidden"]');
      var val = clickedItem.getAttribute('data-value') || clickedItem.textContent.trim();

      if (span) span.textContent = val;
      if (hidden) {
        hidden.value = val;
        hidden.dispatchEvent(new Event('input', { bubbles: true }));
        hidden.dispatchEvent(new Event('change', { bubbles: true }));
      }

      select.querySelectorAll('.dropdown-list__item').forEach(function (it) {
        it.classList.remove('_is-selected');
      });
      clickedItem.classList.add('_is-selected');

      if (list) closeSelect(select, list);
      return;
    }

    var btn = e.target.closest('.dropdown-button');
    if (btn) {
      e.preventDefault();
      var select = btn.closest('.custom-select');
      if (!select) return;
      var list = select.querySelector('.dropdown-list');
      if (!list) return;

      var isActive = select.classList.contains('_is-active');

      document.querySelectorAll('.custom-select._is-active').forEach(function (s) {
        if (s !== select) {
          var otherList = s.querySelector('.dropdown-list');
          if (otherList) closeSelect(s, otherList);
        }
      });

      if (isActive) {
        closeSelect(select, list);
      } else {
        openSelect(select, list);
      }
      return;
    }

    document.querySelectorAll('.custom-select._is-active').forEach(function (s) {
      if (!s.contains(e.target)) {
        var list = s.querySelector('.dropdown-list');
        if (list) closeSelect(s, list);
      }
    });
  });
})();
/* @end: custom-select */
